{"path":"/workspace/source/apps/customer-service/src/erasure-service.ts","command":"create","file_text":"import { createHash } from 'node:crypto';
import { v4 as uuid } from 'uuid';
import type pg from 'pg';
import { transaction } from '../../../packages/database/src/pool.js';
import {
  toErasureResponse,
  type ErasureRequestResponse,
  type ErasureRequestRow,
} from '../../../packages/privacy/src/erasure-contract.js';
import { ErasureRepository } from './erasure-repository.js';

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async create(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestResponse> {
    const customer = await this.repository.findCustomer(merchantId, customerId);
    if (!customer) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });

    const hash = requestHash({ customerId });
    return transaction(async (client) => {
      const replay = await reserveIdempotency(client, merchantId, 'create-erasure-request', idempotencyKey, hash);
      const existing = await this.repository.findByCustomer(client, merchantId, customerId);
      if (existing) {
        const current = existing.status === 'failed'
          ? await this.repository.requeue(client, existing.id) ?? existing
          : existing;
        if (!replay) {
          await completeIdempotency(client, merchantId, 'create-erasure-request', idempotencyKey, 202, toErasureResponse(current));
        }
        await this.repository.audit(client, merchantId, customerId, 'customer.erasure.resumed', uuid(), { requestId: current.id });
        return toErasureResponse(current);
      }

      if (replay) return replay.body as ErasureRequestResponse;

      const created = await this.repository.create(client, merchantId, customerId);
      const body = toErasureResponse(created);
      await completeIdempotency(client, merchantId, 'create-erasure-request', idempotencyKey, 202, body);
      await this.repository.audit(client, merchantId, customerId, 'customer.erasure.requested', uuid(), { requestId: created.id });
      return body;
    });
  }

  async get(merchantId: string, requestId: string): Promise<ErasureRequestResponse | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    return row ? toErasureResponse(row) : undefined;
  }
}

function requestHash(value: unknown): string {
  return createHash('sha256').update(JSON.stringify(value)).digest('hex');
}

async function reserveIdempotency(
  client: pg.PoolClient,
  merchantId: string,
  scope: string,
  key: string,
  hash: string,
): Promise<{ status: number; body: unknown } | undefined> {
  const inserted = await client.query(
    `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
     VALUES($1,$2,$3,$4,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
    [merchantId, scope, key, hash],
  );
  if (inserted.rowCount) return undefined;
  const existing = await client.query<{ request_hash: string; response_status: number | null; response_body: unknown }>(
    `SELECT request_hash,response_status,response_body FROM operations.idempotency_keys
     WHERE merchant_id=$1 AND scope=$2 AND key=$3 FOR UPDATE`,
    [merchantId, scope, key],
  );
  const row = existing.rows[0];
  if (!row || row.request_hash !== hash) {
    throw Object.assign(new Error('idempotency key reused with different request'), { statusCode: 409 });
  }
  if (row.response_status === null) {
    throw Object.assign(new Error('request with this idempotency key is in progress'), { statusCode: 409 });
  }
  return { status: row.response_status, body: row.response_body };
}

async function completeIdempotency(
  client: pg.PoolClient, merchantId: string, scope: string, key: string, status: number, body: unknown,
): Promise<void> {
  await client.query(
    `UPDATE operations.idempotency_keys SET response_status=$4,response_body=$5
     WHERE merchant_id=$1 AND scope=$2 AND key=$3`,
    [merchantId, scope, key, status, body],
  );
}

export type { ErasureRequestRow };
"}

{"path":"/workspace/source/apps/customer-service/src/erasure-worker.ts","command":"create","file_text":"import { createHash } from 'node:crypto';
import { Redis } from 'ioredis';
import { v4 as uuid } from 'uuid';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { config } from '../../../packages/config/src/index.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { nextRetryDelaySeconds } from '../../../packages/operations/src/job-lifecycle.js';
import { type ErasureRequestRow } from '../../../packages/privacy/src/erasure-contract.js';
import { redactJson, uniqueStrings } from '../../../packages/privacy/src/redact.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { ErasureRepository, type CustomerIdentifiers, type StoredObject } from './erasure-repository.js';

const STABLE_ERRORS = {
  cleanup_failed: 'cleanup_failed',
  verification_failed: 'verification_failed',
  search_unavailable: 'search_unavailable',
  storage_unavailable: 'storage_unavailable',
  mail_unavailable: 'mail_unavailable',
} as const;

export class ErasureWorker {
  private lastLeaseRecovery = 0;

  constructor(
    private readonly repository = new ErasureRepository(),
    private readonly redis = new Redis(config().REDIS_URL),
  ) {}

  async run(signal: AbortSignal): Promise<void> {
    while (!signal.aborted) {
      if (Date.now() - this.lastLeaseRecovery > 30_000) {
        await this.repository.recoverExpiredLeases();
        this.lastLeaseRecovery = Date.now();
      }
      const request = await this.repository.claim(`erasure-worker-${process.pid}`);
      if (!request) {
        await new Promise((resolve) => setTimeout(resolve, 250));
        continue;
      }
      try {
        await this.process(request);
        await this.repository.markCompleted(request.id);
      } catch (error) {
        const code = errorCode(error);
        logger.error({ error, requestId: request.id, code }, 'erasure request failed');
        await this.repository.markFailed(request.id, code, nextRetryDelaySeconds(request.attempts));
      }
    }
  }

  async close(): Promise<void> {
    await this.redis.quit();
  }

  private async process(request: ErasureRequestRow): Promise<void> {
    const { merchant_id: merchantId, customer_id: customerId } = request;
    await transaction(async (client) => {
      await this.repository.insertTombstone(client, merchantId, customerId, request.id);
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASED,
        aggregateType: 'customer',
        aggregateId: customerId,
        merchantId,
        correlationId: uuid(),
        payload: { customerId },
      });
    });

    const identifiers = await this.repository.collectIdentifiers(merchantId, customerId);
    await this.deleteCapturedMail(identifiers.emails);

    await transaction(async (client) => {
      await this.repository.deletePersonalRecords(client, merchantId, customerId);
      await this.repository.redactFinancialRecords(client, merchantId, customerId, redactJson);
      await this.repository.redactOperationalRecords(client, merchantId, customerId, identifiers.emails, redactJson);
    });

    const objects = await this.repository.listStoredObjects(merchantId, customerId);
    await this.cleanupStoredObjects(merchantId, customerId, objects, identifiers);

    await this.deleteSearchDocument(merchantId, customerId);
    await this.deleteCache(merchantId, customerId);
    await this.deleteCapturedMail(identifiers.emails);

    await transaction(async (client) => {
      await this.repository.anonymizeCustomer(client, merchantId, customerId);
    });

    const leftovers = await this.repository.remainingPersonalData(merchantId, customerId, identifiers);
    if (leftovers.length) {
      throw Object.assign(new Error(STABLE_ERRORS.verification_failed), { code: STABLE_ERRORS.verification_failed, leftovers });
    }
  }

  private async deleteCapturedMail(emails: string[]): Promise<void> {
    try {
      for (const email of uniqueStrings(emails).filter((value) => value.includes('@') && !value.endsWith('@invalid.example'))) {
        await deleteMailpitMessagesForRecipient(email);
      }
    } catch (error) {
      throw Object.assign(new Error(STABLE_ERRORS.mail_unavailable), { code: STABLE_ERRORS.mail_unavailable, cause: error });
    }
  }

  private async cleanupStoredObjects(
    merchantId: string,
    customerId: string,
    objects: StoredObject[],
    identifiers: CustomerIdentifiers,
  ): Promise<void> {
    for (const object of objects) {
      try {
        const raw = await readObject(object.objectKey);
        const refersToCustomer = object.documentType === 'customer_import'
          || object.importId
          || mentionsIdentifiers(raw, customerId, identifiers);
        if (!refersToCustomer) continue;
        if (object.documentType === 'customer_import' || object.importId) {
          await objectStore.removeObject(DOCUMENT_BUCKET, object.objectKey);
          await transaction(async (client) => {
            await this.repository.deleteImport(client, merchantId, object.objectKey, object.importId);
          });
          continue;
        }
        const rewritten = rewriteStoredDocument(raw);
        await objectStore.putObject(DOCUMENT_BUCKET, object.objectKey, rewritten, Buffer.byteLength(rewritten), {
          'Content-Type': 'application/json',
        });
        await transaction(async (client) => {
          await this.repository.updateManifestChecksum(
            client, merchantId, object.objectKey, createHash('sha256').update(rewritten).digest('hex'),
          );
        });
      } catch (error) {
        if (isMissingObject(error)) continue;
        throw Object.assign(new Error(STABLE_ERRORS.storage_unavailable), { code: STABLE_ERRORS.storage_unavailable, cause: error });
      }
    }
  }

  private async deleteSearchDocument(merchantId: string, customerId: string): Promise<void> {
    try {
      await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: true });
    } catch (error) {
      if (searchStatus(error) === 404) return;
      throw Object.assign(new Error(STABLE_ERRORS.search_unavailable), { code: STABLE_ERRORS.search_unavailable, cause: error });
    }
  }

  private async deleteCache(merchantId: string, customerId: string): Promise<void> {
    const key = `merchant:${merchantId}:customer:${customerId}`;
    await this.redis.del(key, `${key}:activity`);
  }
}

async function readObject(objectKey: string): Promise<string> {
  const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
  const chunks: Buffer[] = [];
  for await (const chunk of stream) chunks.push(Buffer.from(chunk));
  return Buffer.concat(chunks).toString('utf8');
}

function rewriteStoredDocument(raw: string): string {
  try {
    return JSON.stringify(redactJson(JSON.parse(raw)));
  } catch {
    return JSON.stringify({ redacted: true });
  }
}

function mentionsIdentifiers(raw: string, customerId: string, identifiers: CustomerIdentifiers): boolean {
  const haystack = raw.toLowerCase();
  if (haystack.includes(customerId.toLowerCase())) return true;
  return [...identifiers.emails, ...identifiers.names, ...identifiers.phones]
    .some((value) => value && haystack.includes(value.toLowerCase()));
}

function isMissingObject(error: unknown): boolean {
  const code = (error as { code?: string }).code;
  return code === 'NoSuchKey' || code === 'NotFound';
}

function searchStatus(error: unknown): number | undefined {
  const candidate = error as { statusCode?: number; meta?: { statusCode?: number } };
  return candidate.meta?.statusCode ?? candidate.statusCode;
}

function errorCode(error: unknown): string {
  const code = (error as { code?: unknown }).code;
  if (typeof code === 'string' && code.length > 0 && code.length <= 64 && !code.includes('@')) return code;
  return STABLE_ERRORS.cleanup_failed;
}
"}

